import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import b2_scenes as b
D = ("EAR RULE: only Scally and Hopsi have pointed ears; Hal, Titch, Tabitha, Walt and all villagers have round human ears. DYNAMIC COMPOSITION, a low or high camera angle, characters at different heights, mid-action, nobody facing the viewer, no row. ")
SK = "Scally wears only thick grey wool socks, no boots. "
BT = "Scally wears big old brown boots too large for him. "
N = {
 "b65_echo_count": "A rocky ledge high above a gorge. Hal stands counting aloud on his fingers, eyes on the far cliff, mouth shaping the numbers; Walt beside him points across the gap with his hooked pole and grins into his two-way beard; Titch and Tabitha lean over the edge listening; Hopsi watches calmly with her needle; faint pale echo ribbons curve back across the gorge. " + SK,
 "b66_scally_stands": "Dusk on a bog bank. Scally stands up alone from the grass in his grey socks, wind in his black hair, hands open at his sides, speaking quietly to the dark water with a grave honest face; behind him the others sit in a ring watching him, Hal with his slate on his knees, Hopsi pale and still; a small brown bird on Dumpling's ear. Emotional, quiet. " + SK,
 "b67_hopsi_dont_know": "Night at the campfire. Hopsi sits with her hands pressed together in her lap, honest and a little afraid, shaking her head; Titch leans toward her urging, Hal frowns thinking, Tabitha stares into the dark, Walt stares into the flames with an old careworn face, Scally watches Hopsi anxiously; the fire throws warm light on all faces. " + SK,
 "b68_bog_crossing": "Dusk on a bog of reeds and wet grey grass. A single file crosses a narrow green firm path: Old Walt leads with his pole feeling ahead, Gucci nose-down in front picking the way, Titch with a rope looped in her hand, Hopsi, Hal and Tabitha stepping where Walt stepped, Scally last in grey socks, Dumpling plodding behind; reeds mark wet ground; low mist. " + SK,
 "b69_hopsi_in_pot": "Village road in daylight. Hopsi (pointed ears, hops wreath) leans over the big pot and looks into the muddy water with a calm unimpressed expression; Scally stands behind it with a ladle and a face of enormous false honesty; a tired kindly Mrs Crumb waits with a cup; a sign of scribbles stands beside. " + SK,
 "b70_hopsi_warns": "A rain-swept rocky shoulder with a huge lone oak. Hopsi stands in the rain, hair dripping, one hand lifted gently in warning toward the tree; Scally sits smug against the trunk with his arm stretched out as if collecting pennies; Hal and Titch pull their coats over their heads; Walt holds Dumpling's halter, looking up at the dark sky; Tabitha points at the clouds. " + SK,
 "b71_counting_storm": "Dark storm light in a hollow of purple heather. The children crouch low with feet together, hands over ears; Titch holds up fingers counting, face lit white by a distant violet flash across the sky; Hal and Tabitha watch the horizon; Hopsi shields Gucci; Walt holds Dumpling's halter; the great oak stands on the skyline behind. " + SK,
 "b72_scally_pitches": "A wide flat meadow of tall grass with a looping stream. Scally sits on a log in grey socks, pointing across the grass toward a narrow neck of land between loops with a salesman's eager grin; Walt shakes his head firmly, pole in hand; Hal watches with his slate; Titch eats a crust sceptically; Dumpling eats the grass. " + SK,
 "b73_run_high_ground": "A steep slick gorge path in rain. Titch hauls Dumpling by the halter uphill, Tabitha pushes the donkey from behind, Hopsi carries Gucci under one arm like a cushion, Scally scrambles ahead; Hal turns at the top and looks back, horrified; far below on the lower path small Old Walt leans on his pole with a stiff leg and a thin brown tongue of water at his feet. " + SK,
 "b74_going_home": "A calm golden late afternoon beside a low, clear, slow stream running between green banks. Old Walt rides Dumpling smiling with his eel-skin hat tipped over his eyes, stiff leg out; the five children walk the long way home beside him tired and content, Hal carrying his slate, Titch carrying Gucci asleep, Tabitha and Hopsi talking, Scally in grey socks kicking pebbles gently; the mill roof far ahead. " + SK,
 "b75_gucci_dragged": "At the edge of a bog whirlpool a wave runs up the bank and catches baby wolf Gucci's paws, dragging him sliding and yelping toward the spinning dark water; Titch dives flat toward him, arm stretched, red cap flying; Hal grabs the rope; Walt reaches for it too; Hopsi and Tabitha shout; swirling grey mist behind. Urgent but safe. " + SK,
 "b76_the_argument": "The crowded mill yard. Hal's mother, Mrs Crumb and the Mayor all talk at once, hands waving, the Mayor wagging a finger; Old Walt, in the middle, patiently waits leaning on his pole with the donkey beside him; the children stand watching wide-eyed, Hal clutching his slate, Scally edging toward the gate. Warm and funny.",
 "b77_village_sleeps": "A night view of the mill village under a huge moon, every window dark, smoke curling from sleepy chimneys; the mill wheel turning very slowly; on the mill roof a small brown bird sleeps with its head under its wing; the cockerel on a wall asleep; a baker's cat curled on a sill; through one attic window Hal and Gucci are asleep in bed. Peaceful.",
 "b78_egg_spin": "The mill step in sun. Hal spins a cream-coloured egg on the stone step with one finger and it goes round in a tight little ring like a dancer; Hopsi, Titch and Scally (in big brown boots) crowd close watching it with wonder; Scally has his chin on his hands; behind them the long grass and eight more eggs. " + BT,
 "b79_step_buns": "A grey autumn afternoon on the mill step. Hal, Titch, Hopsi, Tabitha and Scally (in big brown boots) sit close together sharing a basket of golden buns, crumbs flying; Gucci asleep sprawled across everyone's feet; on the roof the small brown bird sings; far off in the pond a reflection waves lazily. " + BT,
 "b80_wade_it": "At the bank of a wide dark-green pool where a slipped bank blocks the path. Scally, in grey socks, dips one toe toward the water with a bold grin; Old Walt blocks him sideways with the hooked pole held across, shaking his head, his face stern; Hopsi sits on a stone watching; Hal and Titch look at the water; Gucci sniffs the edge. " + SK,
 "b81_launch_raft": "A raft of six tied logs with a plank deck sits on a green pool; Gucci has one paw on and is falling off with a splash, Hal on board with a long pole, Titch with a rope looped over her shoulder, the other end tied to a tree, Hopsi holding her hops bowl high; on the bank Scally shoves the raft with all his weight, one boot on and one off, red-faced; Tabitha stands watching the water. Walt waves orders from the shore.",
 "b82_painting_sign": "Morning on the mill step. Scally, in big old brown boots, sits painting a board with black paint, tongue between his teeth, brush dripping, the board covered in abstract scribbles; behind a fence in sunshine nine cream-coloured square eggs lie in the long grass; a goose waddles near; Mrs Crumb's black paint pot beside him. " + BT,
}
for k, v in N.items():
    b.S[k] = D + v
if __name__ == "__main__":
    for n in (sys.argv[1:] or list(N)):
        b.gen.edit_with(n, b.REF, b.BASE + b.EXTRA + b.S[n], "3:2")
